<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{agregarFotografia,cerrarNotificacion,eliminarFotografia,listarNotificaciones,urlImpresion,type CierrePayload,type Notificacion}from'../services/notificaciones'
const rows=ref<Notificacion[]>([]),selected=ref<Notificacion|null>(null),loading=ref(false),saving=ref(false),uploading=ref(false),error=ref(''),success=ref(''),search=ref('');const form=reactive<CierrePayload>({tipo_entrega:'bajo puerta',observacion:''});const filtered=computed(()=>{const q=search.value.toLowerCase();return rows.value.filter(x=>`${x.cliente} ${x.codigo} ${x.codigo_sici||''} ${x.distrito} ${x.tipo}`.toLowerCase().includes(q))})
async function load(){loading.value=true;error.value='';try{rows.value=await listarNotificaciones()}catch(e){error.value=msg(e)}finally{loading.value=false}}function open(x:Notificacion){selected.value=x;form.tipo_entrega=x.tipo_entrega as CierrePayload['tipo_entrega']||'bajo puerta';form.observacion=x.observacion||'';error.value=''}async function upload(event:Event){if(!selected.value)return;const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){error.value='Seleccione un archivo de imagen.';return}uploading.value=true;try{const foto=await agregarFotografia(selected.value.id,file);selected.value.fotografias.push(foto);success.value='Fotografía agregada.';input.value=''}catch(e){error.value=msg(e)}finally{uploading.value=false}}async function removePhoto(id:number){if(!selected.value||!confirm('¿Eliminar esta fotografía?'))return;try{await eliminarFotografia(selected.value.id,id);selected.value.fotografias=selected.value.fotografias.filter(x=>x.id!==id)}catch(e){error.value=msg(e)}}async function close(){if(!selected.value)return;if(!form.observacion.trim()){error.value='Registre una observación sobre la entrega.';return}if(!confirm('Al generar la constancia, la notificación dejará la bandeja de pendientes. ¿Continuar?'))return;saving.value=true;try{await cerrarNotificacion(selected.value.id,{...form});rows.value=rows.value.filter(x=>x.id!==selected.value?.id);selected.value=null;success.value='Notificación finalizada correctamente.'}catch(e){error.value=msg(e)}finally{saving.value=false}}function print(){if(selected.value)window.open(urlImpresion(selected.value.id),'_blank')}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Notificaciones</nav><header class="hero"><div class="mark">NT</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Notificaciones por finalizar</h1><p>Control de entrega y evidencia de las notificaciones catastrales.</p></div><div class="counter"><b>{{rows.length}}</b><span>pendientes</span></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="search"><label>Buscar notificación<input v-model.trim="search" placeholder="Cliente, conexión, distrito o tipo"></label></section><div v-if="loading" class="empty">Cargando notificaciones…</div><div v-else-if="!filtered.length" class="empty"><b>Sin notificaciones pendientes</b><span>No existen entregas por finalizar con el criterio indicado.</span></div><section v-else class="cards"><article v-for="x in filtered" :key="x.id"><header><span>{{x.tipo}}</span><small>{{x.fecha_inicio}}</small></header><h2>{{x.cliente}}</h2><p>{{x.distrito}} · {{x.direccion}}</p><div class="codes"><b>{{x.codigo}}</b><span>SICI {{x.codigo_sici||'—'}}</span></div><footer><small>Iniciada por {{x.iniciado_por}}</small><button @click="open(x)">Atender</button></footer></article></section>
<div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><small>NOTIFICACIÓN {{selected.codigo}}</small><h2>{{selected.cliente}}</h2><p>{{selected.tipo}} · {{selected.distrito}}</p></div><button class="x" @click="selected=null">×</button></header><div class="location"><b>{{selected.direccion}}</b><span>Código SICI: {{selected.codigo_sici||'—'}}</span></div><h3>Evidencia fotográfica</h3><label class="uploader"><input type="file" accept="image/*" capture="environment" :disabled="uploading" @change="upload"><span>{{uploading?'Subiendo…':'+ Agregar fotografía'}}</span></label><div v-if="selected.fotografias.length" class="photos"><figure v-for="foto in selected.fotografias" :key="foto.id"><img :src="foto.url" alt="Evidencia de entrega"><figcaption>{{foto.created_at}} <button @click="removePhoto(foto.id)">Eliminar</button></figcaption></figure></div><p v-else class="hint">Aún no se adjuntaron fotografías.</p><h3>Datos de entrega</h3><div class="form"><label>Tipo de entrega<select v-model="form.tipo_entrega"><option value="bajo puerta">Dejado bajo puerta</option><option value="directamente">Entregado al dueño</option><option value="entregado otro">Entregado a un tercero</option></select></label><label>Observación<textarea v-model.trim="form.observacion" rows="3" placeholder="Detalle de la entrega"></textarea></label></div><footer class="buttons"><button class="clear" @click="selected=null">Cancelar</button><button class="print" @click="print">Vista de impresión</button><button :disabled="saving" @click="close">{{saving?'Generando…':'Generar constancia'}}</button></footer></section></div></div></template>
<style scoped>
.page{--a:#b74b50;color:#35454c}nav{margin-bottom:16px;color:#929da2;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.52rem;font-weight:750}.hero h1{margin:2px 0;font-size:1.28rem}.hero p,.modal header p{margin:0;color:#7d898e;font-size:.62rem}.counter{margin-left:auto;text-align:right}.counter b,.counter span{display:block}.counter b{color:var(--a);font-size:1.1rem}.counter span{font-size:.45rem}.flash{padding:10px;font-size:.6rem}.good{color:#277259;background:#eaf8f1}.bad{color:#9d3d42;background:#fff0f0}.search{margin-top:12px;padding:12px;background:#fff}.search label{font-size:.48rem}.search input,input,select,textarea{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.53rem}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{overflow:hidden;border-top:4px solid var(--a);border-radius:8px;background:#fff}.cards article>header,.cards article>footer{padding:9px 12px;display:flex;align-items:center;justify-content:space-between;background:#f8f3f3}.cards article>header span{font-size:.48rem;font-weight:700}.cards small{font-size:.4rem}.cards h2{margin:12px 12px 2px;font-size:.7rem}.cards p{margin:0 12px;color:#748187;font-size:.48rem}.codes{margin:12px;padding:9px;display:flex;justify-content:space-between;background:#f5f7f7;font-size:.5rem}.cards button,.buttons button{padding:7px 10px;border:0;border-radius:4px;color:#fff;background:var(--a);font-size:.46rem}.empty{margin-top:12px;padding:45px;display:grid;gap:5px;text-align:center;background:#fff;font-size:.58rem}.empty span{color:#8a959a}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,760px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.9rem}.x{margin-left:auto;border:0;background:none;font-size:1.4rem}.location{margin:14px 0;padding:10px;display:flex;justify-content:space-between;background:#f5f7f7;font-size:.5rem}.location b,.location span{display:block}.modal h3{margin:16px 0 7px;font-size:.6rem}.uploader input{display:none}.uploader span{display:inline-block;padding:8px;border-radius:4px;color:#fff;background:#327d68;font-size:.47rem}.photos{margin-top:8px;display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.photos figure{margin:0;padding:6px;border:1px solid #e0e6e8;border-radius:5px}.photos img{width:100%;height:110px;object-fit:cover}.photos figcaption{display:flex;justify-content:space-between;color:#7c888d;font-size:.4rem}.photos button{border:0;color:#a43d43;background:none;font-size:.4rem}.hint{color:#8a959a;font-size:.48rem}.form{display:grid;grid-template-columns:1fr 2fr;gap:8px}.form label{font-size:.47rem}.buttons{margin-top:16px;display:flex;justify-content:flex-end;gap:6px}.buttons .clear{color:#607078;background:#edf1f2}.buttons .print{background:#586e78}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:560px){.hero{flex-wrap:wrap}.counter{margin-left:0}.cards,.photos,.form{grid-template-columns:1fr}.location{display:block}}
</style>
